 "Personal del centro": "Ikastetxeko langileak",
 "<b style=\"font-size:25px;color:#b04a3a\">Personal del centro</b><br><span style=\"font-size:21px;color:#2d2616\">Por cuidarlo y cuidarnos.</span>": "<b style=\"font-size:25px;color:#b04a3a\">Ikastetxeko langileak</b><br><span style=\"font-size:21px;color:#2d2616\">Ikastetxea eta gu zaintzeagatik.</span>",
 "Compañeros": "Lagunak",
